CREATE TABLE `banks` (`id` INTEGER NOT NULL AUTO_INCREMENT, `name` VARCHAR(150) NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `banks_name_key`(`name`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `bank_branches` (`id` INTEGER NOT NULL AUTO_INCREMENT, `bank_id` INTEGER NOT NULL, `branch_name` VARCHAR(150) NOT NULL, `branch_code` VARCHAR(50) NULL, `address` VARCHAR(300) NULL, `active` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `bank_branches_bank_id_branch_name_key`(`bank_id`,`branch_name`), PRIMARY KEY (`id`), CONSTRAINT `bank_branches_bank_id_fkey` FOREIGN KEY (`bank_id`) REFERENCES `banks`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `invoice_items` ADD COLUMN `bank_branch_id` INTEGER NULL, ADD CONSTRAINT `invoice_items_bank_branch_id_fkey` FOREIGN KEY (`bank_branch_id`) REFERENCES `bank_branches`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
